blocks.animal_routing:
def _build_route(i, pos, v, day, shed, carry, unlocked_shed, hour=0):
    SPEC = {"COW": (8, 2), "SHEEP": (6, 3), "GOOSE": (4, 1)}
    claimed = set()
    for r in S["routes"].values():
        claimed.update(r["stops"])
    cands = []
    for p2, t in v["animals"]:
        if p2 in claimed:
            continue
        fy, iv = SPEC.get(t.get("animal", "COW"), (8, 2))
        ds = (day + 1) - t.get("placed_day", 0) - fy
        prod_tom = ds >= 0 and iv > 0 and (ds % iv == 0)
        want_feed = day < 29 and (not t.get("fed_today", False)) \
            and (t.get("consecutive_unfed", 0) >= 1 or prod_tom)
        if want_feed or t.get("yield_units", 0) > 0 or t.get("fertilizer_available", False):
            cands.append((p2, t))
    if not cands and hour >= 14:
        best = None
        for j, r in S["routes"].items():
            if j == i or len(r["stops"]) < 2:
                continue
            tp = r["stops"][-1]
            t = v["tiles"][tp[1]][tp[0]]
            fy, iv = SPEC.get(t.get("animal", "COW"), (8, 2))
            ds = (day + 1) - t.get("placed_day", 0) - fy
            wants = day < 29 and (not t.get("fed_today", False)) \
                and (t.get("consecutive_unfed", 0) >= 1 or (ds >= 0 and iv > 0 and ds % iv == 0))
            if wants and carry.get("WHEAT", 0) == 0:
                continue
            gain = _dist(v["positions"][j], tp) - _dist(pos, tp)
            if gain >= 3 and (best is None or gain > best[0]):
                best = (gain, j)
        if best is not None:
            tp = S["routes"][best[1]]["stops"].pop()
            cands = [(tp, v["tiles"][tp[1]][tp[0]])]
    if not cands:
        return None
    stops = []
    cur = pos
    pool = dict(cands)
    while pool and len(stops) < ROUTE_LEN + 2:
        nxt = _nearest(cur, list(pool.keys()))
        if len(stops) >= ROUTE_LEN and _dist(cur, nxt) > 2:
            break
        stops.append(nxt)
        cur = nxt
        del pool[nxt]
    unfed = 0
    for s_ in stops:
        t = v["tiles"][s_[1]][s_[0]]
        if not (isinstance(t, dict) and "animal" in t):
            continue
        fy, iv = SPEC.get(t.get("animal", "COW"), (8, 2))
        ds = (day + 1) - t.get("placed_day", 0) - fy
        if day < 29 and (not t.get("fed_today", False)) \
                and (t.get("consecutive_unfed", 0) >= 1 or (ds >= 0 and iv > 0 and ds % iv == 0)):
            unfed += 1
    need = max(0, unfed - carry.get("WHEAT", 0))
    pickup = min(need, S["wheat_budget"]) if unlocked_shed else 0
    S["wheat_budget"] -= pickup
    return {"stops": stops, "pickup": pickup}


def _route_step(i, pos, v, day, hour, shed, carry, unlocked_shed):
    SPEC = {"COW": (8, 2), "SHEEP": (6, 3), "GOOSE": (4, 1)}
    r = S["routes"][i]
    tiles = v["tiles"]
    if r["pickup"] > 0:
        if pos in unlocked_shed:
            n = min(r["pickup"], shed.get("WHEAT", 0))
            r["pickup"] = 0
            if n > 0:
                return ["PICKUP", "WHEAT", int(n)]
            if hour <= 1:
                r["pickup"] = 1
                return ["PASS"]
        else:
            return [_step(pos, _nearest(pos, unlocked_shed))]
    while r["stops"]:
        tgt = r["stops"][0]
        t = tiles[tgt[1]][tgt[0]]
        if not (isinstance(t, dict) and "animal" in t):
            r["stops"].pop(0)
            continue
        fy, iv = SPEC.get(t.get("animal", "COW"), (8, 2))
        ds = (day + 1) - t.get("placed_day", 0) - fy
        prod_tom = ds >= 0 and iv > 0 and (ds % iv == 0)
        want_feed = day < 29 and (not t.get("fed_today", False)) \
            and (t.get("consecutive_unfed", 0) >= 1 or prod_tom)
        if pos != tgt:
            return [_step(pos, tgt)]
        if want_feed and carry.get("WHEAT", 0) > 0:
            return ["FEED"]
        if want_feed and carry.get("WHEAT", 0) == 0 and S["wheat_budget"] > 0 and hour < 21 and not r.get("refilled"):
            need = 0
            for s_ in r["stops"]:
                t2 = tiles[s_[1]][s_[0]]
                if not (isinstance(t2, dict) and "animal" in t2):
                    continue
                fy2, iv2 = SPEC.get(t2.get("animal", "COW"), (8, 2))
                ds2 = (day + 1) - t2.get("placed_day", 0) - fy2
                if (not t2.get("fed_today", False)) \
                        and (t2.get("consecutive_unfed", 0) >= 1 or (ds2 >= 0 and iv2 > 0 and ds2 % iv2 == 0)):
                    need += 1
            r["pickup"] = min(need, S["wheat_budget"])
            S["wheat_budget"] -= r["pickup"]
            r["refilled"] = True
            if r["pickup"] <= 0:
                r["pickup"] = 0
            elif pos in unlocked_shed:
                return ["PICKUP", "WHEAT", int(r["pickup"])]
            else:
                return [_step(pos, _nearest(pos, unlocked_shed))]
        if day < 28 and (not t.get("cared_today", False)) and t.get("fed_today", False):
            return ["CARE"]
        if t.get("fertilizer_available", False):
            return ["COLLECT_FERTILIZER"]
        if t.get("yield_units", 0) > 0:
            return ["HARVEST"]
        r["stops"].pop(0)
    del S["routes"][i]
    return None
